12	// Remove the linking and embedding logic from the Xcode project to give the tool more control over these.
13	class RemoveMacOSFrameworkLinkAndEmbeddingMigration extends ProjectMigrator {
14	  RemoveMacOSFrameworkLinkAndEmbeddingMigration(
15	    MacOSProject project,
16	    Logger logger,
17	    Usage usage,
18	  )   : _xcodeProjectInfoFile = project.xcodeProjectInfoFile,
19	        _usage = usage,
20	        super(logger);
21	
22	  final File _xcodeProjectInfoFile;
23	  final Usage _usage;
24	
25	  @override
26	  bool migrate() {
27	    if (!_xcodeProjectInfoFile.existsSync()) {
28	      logger.printTrace(
29	          'Xcode project not found, skipping framework link and embedding migration');
30	      return true;
31	    }
32	
33	    processFileLines(_xcodeProjectInfoFile);
34	
35	    return true;
36	  }
37	
38	  @override
39	  String migrateLine(String line) {
40	    // App.framework Frameworks reference.
41	    // isa = PBXFrameworksBuildPhase;
42	    // files = (
43	    //     D73912F022F37F9E000D13A0 /* App.framework in Frameworks */,
44	    if (line.contains('D73912F022F37F9E000D13A0')) {
45	      return null;
46	    }
47	
48	    // App.framework Embed Framework reference (build phase to embed framework).
49	    // D73912F222F3801D000D13A0 /* App.framework in Bundle Framework */,
50	    if (line.contains('D73912F222F3801D000D13A0')) {
51	      return null;
52	    }
53	
54	    // App.framework project file reference (seen in Xcode navigator pane).
55	    // isa = PBXGroup;
56	    // children = (
57	    //	  D73912EF22F37F9E000D13A0 /* App.framework */,
58	    if (line.contains('D73912EF22F37F9E000D13A0')) {
59	      return null;
60	    }
61	
62	    // FlutterMacOS.framework Frameworks reference.
63	    // isa = PBXFrameworksBuildPhase;
64	    // files = (
65	    //   33D1A10422148B71006C7A3E /* FlutterMacOS.framework in Frameworks */,
66	    if (line.contains('33D1A10422148B71006C7A3E')) {
67	      return null;
68	    }
69	
70	    // FlutterMacOS.framework Embed Framework reference (build phase to embed framework).
71	    // 33D1A10522148B93006C7A3E /* FlutterMacOS.framework in Bundle Framework */,
72	    if (line.contains('33D1A10522148B93006C7A3E')) {
73	      return null;
74	    }
75	
76	    // FlutterMacOS.framework project file reference (seen in Xcode navigator pane).
77	    // isa = PBXGroup;
78	    // children = (
79	    //	 33D1A10322148B71006C7A3E /* FlutterMacOS.framework */,
80	    if (line.contains('33D1A10322148B71006C7A3E')) {
81	      return null;
82	    }
83	
84	    // Embed frameworks in a script instead of using Xcode's link / embed build phases.
85	    const String thinBinaryScript = r'/Flutter/ephemeral/.app_filename';
86	    if (line.contains(thinBinaryScript) && !line.contains(' embed')) {
87	      return line.replaceFirst(
88	          thinBinaryScript, r'/Flutter/ephemeral/.app_filename && \"$FLUTTER_ROOT\"/packages/flutter_tools/bin/macos_assemble.sh embed');
89	    }
90	
91	    if (line.contains('/* App.framework ') ||
92	        line.contains('/* FlutterMacOS.framework ')) {
93	      UsageEvent('macos-migration', 'remove-frameworks',
94	              label: 'failure', flutterUsage: _usage)
95	          .send();
96	      throwToolExit(
97	          'Your Xcode project requires migration.');
98	    }
99	
100	    return line;
101	  }
102	}
